Translate("ruRU", "darkshore", {
	title = "Темные берега",
	sections = {
		{
			title = "Обзор",
			text = [=[Темные берега — длинное серое побережье на северо-западе {link:kalimdor}Калимдора{/link}, отделенное узким проливом от великого древа {link:teldrassil}Тельдрассил{/link}. Его леса сумрачны даже в полдень, его пляжи холодны, а его холмы полны руин, которые старше любого королевства людей. {link:night-elves}Ночные эльфы{/link} держат его из маленького портового городка {link:auberdine}Аубердин{/link}. Они сделали его воротами между своим новым домом и большим миром. Но земля, которую они стерегут, больна. Ее реки текут грязными, ее звери обезумели, и старые враги вернулись в руины собственного прошлого эльфов.]=],
		},
		{
			title = "Истоки",
			text = [=[Задолго до {link:great-sundering}Великого Раскола{/link} эти холмы смотрели сверху на берега {link:well-of-eternity}Источника Вечности{/link}. Здесь {link:queen-azshara}королева Азшара{/link} возвела для своих любимых высокорожденных города-близнецы {link:ameth-aran}Амет'Аран{/link} и {link:bashal-aran}Башал'Аран{/link} и поставила править ими из Башни Алталакса лорда {link:athrikus-narassin}Атрикус{/link}а {link:nara-wildmane}Нара{/link}ссина. Когда {link:war-of-the-ancients}Война древних{/link} закончилась и Источник был уничтожен, города пали, а землю разорвало. То, что осталось, стало побережьем нового моря. На севере рассыпались руины Матистры, некогда великого оплота эльфов. После {link:battle-of-mount-hyjal}битвы у горы Хиджал{/link} ночные эльфы вырастили у этого побережья {link:teldrassil}Тельдрассил{/link}. Ни одна летопись не называет года, когда был построен {link:auberdine}Аубердин{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:auberdine}Аубердин{/link} — скромный городок, но оживленный. Корабли везут путников на {link:teldrassil}Тельдрассил{/link} и через море в земли людей. Новое судно связывает его теперь с {link:stormwind-harbor}Гаванью Штормграда{/link}, а другое ходит через {link:southshore}Южнобережье{/link} в {link:menethil-harbor}Гавань Менетилов{/link}. Городу нужен каждый друг, какого могут привезти эти корабли. {link:furbolgs}Фурболги{/link} Чернолесья обратились против эльфов. Среди чертополоховых медведей и оленей расходится болезнь, и течет она, похоже, из {link:felwood}Оскверненного леса{/link} на востоке. {link:naga}Наги{/link} держат руины Матистры. {link:twilight-s-hammer}Сумеречный Молот{/link} ведет раскопки у Меча Властителя, а в Башне Алталакса собирается культ чернокнижников. Когда старейшина Аубердина попросил {link:stormwind-city}Штормград{/link} о помощи, Штормграду нечего было дать. {link:darnassus}Дарнасс{/link} прислал немногим больше.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:night-elves}Ночные эльфы{/link} {link:auberdine}Аубердин{/link}а.{/b} {link:sentinels}Часовые{/link}, друиды и ученые, которые хранят город и изучают порчу, что его окружает.
• {b}{link:dwarves}Дворфы{/link}.{/b} Рудокопы, кузнецы и торговцы из {link:ironforge}Стальгорна{/link} и ученые {link:explorers-league}Лиги исследователей{/link}, которые ведут раскопки на юге.
• {b}{link:blackwood-furbolgs}Фурболги Чернолесья{/link}.{/b} Некогда друзья эльфов, ныне обезумевшие и враждебные в своих лагерях.
• {b}{link:naga}Наги{/link}.{/b} Наги Грозовой Чешуи обитают в Матистре и в пещере за Водопадом Скалистым.
• {b}{link:murlocs}Мурлоки{/link} Серой Мглы.{/b} Они теснятся на побережье и нападают на корабли и рыбаков.
• {b}Неупокоенные мертвецы.{/b} Духи высокорожденных все еще бродят по руинам {link:ameth-aran}Амет'Аран{/link}а.
• {b}Совухи.{/b} Они бродят по восточным холмам и с каждым временем года становятся все враждебнее.]=],
		},
		{
			title = "История",
			text = [=[• {b}Города-близнецы.{/b} В век королевы Азшары {link:ameth-aran}Амет'Аран{/link} и {link:bashal-aran}Башал'Аран{/link} процветали у Источника Вечности, пока мир под ними скатывался к безумию.
• {b}{link:great-sundering}Раскол{/link}.{/b} В хаосе войны {link:athrikus-narassin}Атрикус Нарассин{/link} обещал жителям Амет'Арана вечную жизнь через свою магию. Их духи так и не обрели покоя.
• {b}Долгий сон.{/b} Многие друиды последовали за {link:malfurion-stormrage}Малфурионом Яростью Бури{/link} в сон {link:emerald-dream}Изумрудного Сна{/link}. Некоторые из спавших недавно пробудились и находят свои старые дома в руинах.
• {b}Новый дом.{/b} После войны с {link:burning-legion}Пылающим Легионом{/link} ночные эльфы сделали {link:teldrassil}Тельдрассил{/link} своим домом, и {link:auberdine}Аубердин{/link} стал его дверью в мир.]=],
		},
		{
			title = "Предания берега",
			text = [=[• Огромные морские создания все чаще выбрасываются на пляжи Темных берегов. Жрицы Храма Луны узнали, что их гонят наги.
• В восточных холмах стоит красный кристалл. Внутри него лежат обломки костей и половина челюсти. Вокруг него собираются совухи, и никто не знает почему.
• Рыбаки {link:auberdine}Аубердин{/link}а больше не выводят лодки в море. Они говорят, что {link:murlocs}мурлок{/link}и съели всех морских окуней.]=],
		},
	},
})

Translate("ruRU", "auberdine", {
	title = "Аубердин",
	sections = {
		{
			title = "Обзор",
			text = [=[Аубердин — портовый город Темных берегов, построенный на побережье напротив {link:teldrassil}Тельдрассил{/link}а. Им правят его старейшина, {link:thundris-windweaver}Тандрис Ткач Ветров{/link}, и деревенский совет. Его стерегут {link:sentinels}Часовые{/link}, а лунный колодец в его сердце дает чистую воду, которая нужна его друидам и жрицам. {link:night-elves}Ночные эльфы{/link} и {link:dwarves}дворф{/link}ы делят его таверну, его кузницы и его причалы. С его пирсов один корабль ходит в Деревню {link:rut-theran-village}Рут'теран{/link} под Тельдрассилом, а другой плывет в {link:menethil-harbor}Гавань Менетилов{/link}. Теперь появились два новых пути: один — в {link:stormwind-harbor}Гавань Штормграда{/link} и один — в Гавань Менетилов через {link:southshore}Южнобережье{/link} в {link:hillsbrad-foothills}Предгорьях Хилсбрада{/link}. Город надеется, что корабли привезут помощь. Пока они привозили только путников.]=],
		},
	},
})

Translate("ruRU", "ruins-of-mathystra", {
	title = "Руины Матистры",
	aliases = { "Матистра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Матистры лежат на дальнем северо-востоке Темных берегов. Матистра некогда была великим оплотом эльфов, и осколки ее магии все еще лежат среди травы и разбитых камней. Теперь ее держат {link:naga}наги{/link} Грозовой Чешуи, и они грабят место, которое их собственные предки когда-то звали домом. Их повелительницы зверей подчиняют своей воле {link:ogres}огр{/link}омных тварей моря. А недавно под руинами нашлось нечто более древнее. Страж-элементаль охранял лестницу, которая ведет вниз, во тьму, и даже Древние пока не знают, что лежит внизу.]=],
		},
	},
})

Translate("ruRU", "bashal-aran", {
	title = "Башал'Аран",
	sections = {
		{
			title = "Обзор",
			text = [=[Башал'Аран был одним из городов-близнецов, которые королева {link:azshara}Азшара{/link} возвела для своих высокорожденных. Его руины лежат к востоку от {link:auberdine}Аубердин{/link}а. Демонические духи, греллы и {link:satyrs}сатир{/link}ы шайки Дет'рилл устроили в них свое логово и становятся сильнее, питаясь магией, которая все еще держится на камнях. Но есть одно святилище на утесе на западе руин, к которому они не приближаются. Вокруг него висит синий свет. Внутри ждет дух {link:asterion}Астерион{/link}, скованный там собственным господином дольше, чем помнит любой живой эльф.]=],
		},
	},
})

Translate("ruRU", "ameth-aran", {
	title = "Амет'Аран",
	sections = {
		{
			title = "Обзор",
			text = [=[Амет'Аран был близнецом {link:bashal-aran}Башал'Аран{/link}а, городом высокорожденных у Источника Вечности. Он был разрушен в войне, которая расколола мир. Его жители не умерли по-настоящему. Они ухватились за обещание, которое дал им {link:athrikus-narassin}Атрикус Нарассин{/link}, и теперь бродят по руинам проклятыми стенающими духами, все еще неся магические орудия своего старого ремесла. Две большие скрижали среди камней рассказывают историю города и его падения. Здесь до сих пор горит древнее синее пламя. Оно достаточно жарко, чтобы уничтожить то, чего не берет никакой другой огонь.]=],
		},
	},
})

Translate("ruRU", "tower-of-althalaxx", {
	title = "Башня Алталакса",
	sections = {
		{
			title = "Обзор",
			text = [=[Башня Алталакса высится на северо-востоке Темных берегов. В ней пребывал {link:athrikus-narassin}Атрикус Нарассин{/link} — лорд высокорожденных, который правил городами {link:ameth-aran}Амет'Аран{/link} и {link:bashal-aran}Башал'Аран{/link} от имени королевы и большую часть дней проводил вдали от них, здесь. Спустя десять тысяч лет у башни снова есть хозяин. Ее захватил отряд чернокнижников, который называет себя культом Темной Пряди, и сильнейшие из них держатся в верхних покоях. {link:morgan-s-vigil}Дозор{/link}ный {link:auberdine}Аубердин{/link}а, {link:balthule-shadowstrike}Балтул Удар Тени{/link}, стоит лагерем неподалеку. Он видел вспышки света с вершины башни и слышал крики.]=],
		},
	},
})

Translate("ruRU", "grove-of-the-ancients", {
	title = "Роща Древних",
	sections = {
		{
			title = "Обзор",
			text = [=[Роща Древних лежит на юге Темных берегов, под защитой гор. Здесь обитают Древние — великие духи леса, которые стоят рядом с ночными эльфами с самых давних дней. {link:onu}Ону{/link}, Древний Знаний, собирает вести о каждой угрозе в этой земле, и друиды {link:auberdine}Аубердин{/link}а внимают его предостережениям. Рядом с ним стоит {link:arbal}Арбал{/link}, Древний Войны. Роща терпелива, как все Древние, но не праздна. Отсюда тихо готовится борьба с {link:naga}нага{/link}ми и Сумеречным Молотом.]=],
		},
	},
})

Translate("ruRU", "twilight-vale", {
	title = "Сумеречная долина",
	sections = {
		{
			title = "Обзор",
			text = [=[Сумеречной долиной называют южные леса Темных берегов, от руин {link:ameth-aran}Амет'Аран{/link}а до границ {link:ashenvale}Ясеневого леса{/link}. Ее дороги связывают {link:auberdine}Аубердин{/link} с Заставой Мейстры и {link:astranaar}Астранаар{/link}ом, и гонцы ездят по ним на свой страх. {link:blackwood-furbolgs}Фурболги Чернолесья{/link} устраивают засады на путников, среди деревьев рыщут лунные охотники, а больные медведи леса нападают на всякого, кто подойдет близко. {link:grove-of-the-ancients}Роща Древних{/link}, {link:the-master-s-glaive}Меч Властителя{/link} и раскопки Лиги исследователей — все они лежат в пределах долины. Те, кто едет через нее, держатся дороги.]=],
		},
	},
})

Translate("ruRU", "mist-s-edge", {
	title = "Туманный Предел",
	sections = {
		{
			title = "Обзор",
			text = [=[Туманный Предел — длинная серая вода вдоль побережья Темных берегов, где {link:cliffspring-river}Река Скалистая{/link} впадает в море. Его пляжи усеяны тушами {link:ogres}огр{/link}омных морских созданий и обломками кораблей. Два из этих кораблей, «Серебряная Заря» и «Туманная завеса», лежат на дне к северу от {link:auberdine}Аубердин{/link}а: их потопили {link:murlocs}мурлок{/link}и, когда они входили в гавань. По каждой полосе песка снуют крабы. Мурлоки Серой Мглы ставят свои хижины вдоль берега, а их вожаки охотятся и на рыбаков, и на Часовых.]=],
		},
	},
})

Translate("ruRU", "cliffspring-river", {
	title = "Река Скалистая",
	sections = {
		{
			title = "Обзор",
			text = [=[Река Скалистая спускается с восточных гор и бежит к морю к северу от {link:auberdine}Аубердин{/link}а. Над первым ее водопадом переброшен мост. Некогда ее вода была чистой. Теперь она портится, и старейшина Аубердина боится, что зараза дойдет до самого города. Вдоль ее берегов стоят северные лагеря {link:furbolgs}фурболг{/link}ов Чернолесья, и у воды горят их костры. {link:thundris-windweaver}Тандрис Ткач Ветров{/link} считает, что реку оскверняют фурболги, но что истинный корень яда лежит дальше на востоке, в Оскверненном лесу.]=],
		},
	},
})

Translate("ruRU", "cliffspring-falls", {
	title = "Водопад Скалистый",
	sections = {
		{
			title = "Обзор",
			text = [=[Водопад Скалистый низвергается с гор к востоку от {link:auberdine}Аубердин{/link}а. Из него пьет большая часть края, и теперь в его водах течет яд, от которого болеют олени Темных берегов. За водопадом лежит пещера, где растут редкие грибы. Древние предостерегали жителей Аубердина держаться от нее подальше, ибо чуяли, что там поселилось новое зло. Они были правы. Пещеру захватили наги, и ведет их повелитель наг {link:lord-sinslayer}Убийца Грехов{/link}.]=],
		},
	},
})

Translate("ruRU", "blackwood-den", {
	title = "Берлога в Чернолесье",
	sections = {
		{
			title = "Обзор",
			text = [=[Берлога в Чернолесье лежит на дальнем юге Темных берегов, у границы Ясеневого леса. Это скопление лагерей {link:furbolgs}фурболг{/link}ов вокруг небольшой пещеры, и принадлежит оно племени Чернолесья. Ночного эльфа {link:volcor}Волкор{/link}а здесь ранили фурболги, и он укрылся в глубине пещеры. Его верный спутник, {link:grimclaw}Мрачный Коготь{/link}, один ушел на север искать помощь. Берлога — мрачный знак того, как низко пали фурболги. Некогда они жили в мире с эльфами. Теперь они нападают на любого эльфа, который забредет к их кострам.]=],
		},
	},
})

Translate("ruRU", "remtravel-s-excavation", {
	title = "Раскопки рассеянного геолога",
	aliases = { "раскопки геолога Ремтравела" },
	sections = {
		{
			title = "Обзор",
			text = [=[Раскопки рассеянного геолога — раскоп {link:explorers-league}Лиги исследователей{/link} на юго-западе Темных берегов. Здесь геолог {link:prospector-remtravel}Ремтравел{/link} и его люди открыли следы великого и древнего общества. Потом сама земля обратилась против них. Из земли поднялись каменные големы и заполонили раскоп, а с ними пришли {link:troggs}трогги{/link} Гравийного Кремня. {link:humans}Люди{/link} геолога бежали в {link:auberdine}Аубердин{/link}. Сам геолог не бежал. Он все еще где-то на раскопе и ищет загадочную окаменелость, которую однажды уже потерял. Что Лига сделает с этой окаменелостью, никто в Аубердине сказать не может.]=],
		},
	},
})

Translate("ruRU", "the-master-s-glaive", {
	title = "Меч Властителя",
	aliases = { "Меч Властителя" },
	sections = {
		{
			title = "Обзор",
			text = [=[Меч Властителя стоит на юге Темных берегов: громадный клинок, вогнанный в череп павшего исполина. {link:onu}Ону{/link} учит, что здесь в минувшие века погиб один из древних владык земли, пронзенный этим клинком. Владыка давно мертв, но в его костях могут оставаться крупицы его силы. {link:twilight-s-hammer}Сумеречный Молот{/link} пришел их искать. Его сектанты стоят лагерем под клинком, и в их книгах есть страницы древней эльфийской магии, искаженной, чтобы призвать их старых господ обратно в мир.]=],
		},
	},
})

Translate("ruRU", "thundris-windweaver", {
	title = "Тандрис Ткач Ветров",
	subtitle = "Старейшина Аубердина",
	found = "Аубердин, на верхнем этаже ратуши",
	hint = [=[Разыщите старейшину, который ведает повседневными делами Аубердина.]=],
	allegiance = "Аубердин · ночные эльфы",
	aliases = { "Тандрис" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тандрис Ткач Ветров — старейшина {link:auberdine}Аубердин{/link}а. Он ведет повседневные дела города справедливой и твердой рукой. Он же — самый з{link:orcs}орк{/link}ий в городе знаток порчи. Он уже видел эту болезнь прежде, в давно минувшие времена, и знает, что она не останавливается у границ леса.]=],
		},
		{
			title = "Значение",
			text = [=[Тандрис видит беду Темных берегов целиком. Ярость {link:furbolgs}фурболг{/link}ов, грязная река и орудия древних высокорожденных для него — части одной войны. Еще он хочет, чтобы об {link:auberdine}Аубердин{/link}е знали. Великие города помнят лишь то, что {link:great-sundering}Великий Раскол{/link} отнял у ночных эльфов. Он хотел бы, чтобы они помнили город, который все еще стоит.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он проследил отравление Реки Скалистой до Оскверненного леса.
• Он узнал, что {link:satyrs}сатир{/link}ы оскверняют {link:furbolgs}фурболг{/link}ов Чернолесья через талисманы.
• По его велению магические реликвии высокорожденных {link:ameth-aran}Амет'Аран{/link}а собирают и уничтожают.
• Он очищает самоцветы Кор, отнятые у наг, для тех, кто идет святым путем.
• Он написал в {link:stormwind-city}Штормград{/link} с просьбой о помощи.]=],
		},
	},
	chapters = {
		{
			title = "Оскверненное Чернолесье",
			hint = "Выманите сатира, который мучает северных фурболгов.",
			text = [=[Тандрис смешал воду лунного колодца с пищей самих {link:furbolgs}фурболг{/link}ов и велел поставить ее у их костра. Те, кто поел, на миг очистились. В этот миг {link:satyrs}сатир{/link}, державший их в рабстве, вышел посмотреть, что пошло не так. Его талисман принесли в {link:auberdine}Аубердин{/link}. Тандрис назвал это одной выигранной битвой в долгой войне.]=],
		},
		{
			title = "Орудия высокорожденных",
			hint = [=[Отнимите реликвии древних высокорожденных у духов Амет'Арана.]=],
			text = [=[Духи {link:ameth-aran}Амет'Аран{/link}а все еще носят с собой орудия своей магии. Тандрис жалеет, что эти орудия не сгинули в катаклизме, который покончил с их миром. Раз они не сгинули, он уничтожит их сам.]=],
		},
		{
			title = "Письмо через море",
			hint = "Отвезите письмо старейшины в Штормград и привезите ответ.",
			text = [=[Тандрис отправил на новом корабле письмо в {link:stormwind-city}Штормград{/link}, и получил его {link:baros-alexston}Барос Алекстон{/link}. Ответ был любезен и пуст. Штормграду нечем было поделиться. Тандрис принял это спокойно. Если ни Штормград, ни {link:darnassus}Дарнасс{/link} не придут, сказал он, то {link:auberdine}Аубердин{/link} сам решит свою судьбу.]=],
		},
	},
	mentions = {
		{
			text = [=[«Тандрис Ткач Ветров», по поручению эльфа {link:terenthis}Терентис{/link}а]=],
		},
		{ text = "«{link:bashal-aran}Башал'Аран{/link}»" },
		{ text = "«{link:cliffspring-river}Река Скалистая{/link}»" },
		{ text = "«В поисках самоцвета Кор»" },
		{ text = "«Расширяя горизонты»" },
		{ text = "«Это все шутки, пока...», око древнего зла" },
	},
	bonds = {
		{ id = "terenthis", name = "Терентис", note = "шлет ему вести о фурболгах" },
		{ id = "asterion", name = "Астерион", note = "дух, искать которого он посылал чужаков" },
		{ id = "baros-alexston", name = "Барос Алекстон", note = "ответил на его письмо" },
		{ id = "sentinel-glynda-nal-shea", name = "Часовая Глинда Нал'Шеа", note = "хранит покой его города" },
	},
})

Translate("ruRU", "terenthis", {
	title = "Терентис",
	subtitle = "Наблюдатель за Чернолесьем",
	found = "Аубердин, близ поста Часовых",
	hint = [=[Поговорите в Аубердине с ночным эльфом, который выслеживает признаки порчи.]=],
	allegiance = "Аубердин · ночные эльфы",
	sections = {
		{
			title = "Обзор",
			text = [=[Терентис — {link:night-elves}ночной эльф{/link} из {link:auberdine}Аубердин{/link}а, который поклялся найти порчу у самого ее источника. Некоторых его сородичей спасли от оскверненного {link:furbolgs}фурболг{/link}а на {link:teldrassil}Тельдрассил{/link}е. С того дня он дал обет, что никто больше из его народа не пострадает так же, и пристально следит за фурболгами Темных берегов.]=],
		},
		{
			title = "Значение",
			text = [=[Терентис одним из первых показал, как близко подошла опасность. Его разведчики нашли оскверненные лагеря Чернолесья в виду {link:auberdine}Аубердин{/link}а. Он также друг тем, кто живет один в глуши, и друг в беде находит его готовым помочь.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он послал разведчиков найти оскверненный лагерь {link:furbolgs}фурболг{/link}ов и бойцов — проредить их ряды.
• Он сшил зачарованный плащ из шкур лунных охотников, который позволял тому, кто его носит, ходить невидимым для зверей Темных берегов.
• Он вернул домой эльфа {link:volcor}Волкор{/link}а из Берлоги в {link:blackwood-furbolgs}Чернолесье{/link}.
• Он шлет свои находки старейшине {link:thundris-windweaver}Тандрис{/link}у {link:weaver}Ткач{/link}у Ветров.]=],
		},
	},
	chapters = {
		{
			title = "Насколько велика угроза?",
			hint = "Найдите оскверненный лагерь фурболгов близ Аубердина.",
			text = [=[Лагерь к югу от {link:auberdine}Аубердин{/link}а оказался хуже, чем Терентис опасался. {link:blackwood-furbolgs}Фурболги Чернолесья{/link} были осквернены, и они были близко. Он велел Аубердину готовиться к тому, что должно прийти. Тем же, кто там сражался, он сказал не скорбеть. Они уменьшили угрозу, пусть даже мох скверны все еще отравлял землю.]=],
		},
		{
			title = "Пропавший хозяин",
			hint = "Откликнитесь на зов зверя, который пришел в Аубердин один.",
			text = [=[{link:grimclaw}Мрачный Коготь{/link} пришел в {link:auberdine}Аубердин{/link} без хозяина. Терентис понял все сразу. {link:volcor}Волкор{/link} был ранен где-то на юге, среди {link:furbolgs}фурболг{/link}ов. Он сшил плащ, который скроет своего носителя от зверей, и предупредил, что магия плаща иссякнет, если носитель сделает что-то большее, чем заговорит.]=],
		},
	},
	mentions = {
		{ text = "«Пропавший хозяин»" },
		{ text = "«Побег силой»" },
		{ text = "«Побег украдкой»" },
		{ text = "«{link:thundris-windweaver}Тандрис Ткач Ветров{/link}»" },
		{
			text = [=[«Путь в {link:ashenvale}Ясеневый лес{/link}», зов Часовой Селарин]=],
		},
	},
	bonds = {
		{ id = "volcor", name = "Волкор", note = "его друг" },
		{ id = "grimclaw", name = "Мрачный Коготь", note = "спутник его друга" },
		{ id = "thundris-windweaver", name = "Тандрис Ткач Ветров", note = "старейшина, которому он докладывает" },
		{ id = "blackwood-furbolgs", name = "Фурболги Чернолесья", note = "порча, за которой он следит" },
	},
})

Translate("ruRU", "onu", {
	title = "Ону",
	subtitle = "Древний Знаний",
	found = "Роща Древних, на юге Темных берегов",
	hint = "Ищите Древнего Знаний в роще у южных гор.",
	allegiance = "Древние · Роща Древних",
	sections = {
		{
			title = "Обзор",
			text = [=[Ону — Древний Знаний, один из великих духов леса, и он хранит Рощу Древних на юге Темных берегов. Он говорит медленно, с долгими паузами, и не спешит. Он знает, что все свершается в назначенный срок.]=],
		},
		{
			title = "Значение",
			text = [=[Ону — память Темных берегов. Он знает, чему поклоняются сектанты Сумеречного Молота, и знает, где пал один из их древних владык. Друиды и ученые {link:auberdine}Аубердин{/link}а шлют ему свои самые тяжкие вопросы, а верховный друид {link:fandral-staghelm}Фэндрал Олений Шлем{/link} шлет ему послания из {link:darnassus}Дарнасс{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он послал наблюдателей к Мечу Властителя и узнал, что там находится {link:twilight-s-hammer}Сумеречный Молот{/link}.
• Он изучил страницу, вырванную из фолианта культа, и почуял в ней магию древних.
• Он собрал реликвии из Матистры, чтобы узнать, как культ пользуется эльфийской магией.
• Он говорит о том, кого зовет {link:malfurion-stormrage}шан'до Ярость Бури{/link}, как о постигшем терпение леса.]=],
		},
	},
	chapters = {
		{
			title = "Меч Властителя",
			hint = "Отправьтесь к Мечу Властителя по просьбе Древнего.",
			text = [=[Ону счел странным, что наги пришли на {link:darkshore}Темные берега{/link}. Еще более странным он счел то, что пришел {link:twilight-s-hammer}Сумеречный Молот{/link}. Когда его опасения подтвердились, он рассказал о древнем владыке, пронзенном у Меча. Тот владыка мертв. Его сила, быть может, нет.]=],
		},
		{
			title = "Страницы древних",
			hint = "Принесите Древнему то, что было взято в лагере культа.",
			text = [=[Каракули, вырванные из Сумеречного фолианта, таили хаотическую магию, а под ней лежало письмо эльфов. Культ использовал древнее эльфийское чародейство, чтобы вернуть в мир своих старых господ. Ону взялся узнать как, прежде чем его враги завершат начатое.]=],
		},
		{
			title = "Лестница под Матистрой",
			hint = "Принесите Древнему то, что осталось от стража Матистры.",
			text = [=[Когда перед ним положили шар помутневшей воды, Ону выказал нечто близкое к удивлению. Под Матистрой была лестница, и ее охранял страж. Он сказал лишь, что должен поговорить с другими Древними и что хорошо, что лестницу нашли прежде, чем ее нашли наги или культ.]=],
		},
	},
	mentions = {
		{
			text = [=[«Ону», по зову эльфа {link:barithras-moonshade}Баритрас{/link}а Лунной Тени]=],
		},
		{ text = "«{link:twilight-base-camp}Сумеречный лагерь{/link}»" },
		{
			text = [=[«{link:grove-of-the-ancients}Роща Древних{/link}», послание от верховного друида {link:fandral-staghelm}Фэндрал{/link}а Оленьего Шлема]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "Арбал", note = "стоит рядом с ним в роще" },
		{ id = "barithras-moonshade", name = "Баритрас Лунная Тень", note = "внимает его предостережениям" },
		{ id = "fandral-staghelm", name = "Фэндрал Олений Шлем", note = "шлет ему вести" },
		{ id = "baron-marinous", name = "барон Маринус", note = "страж Матистры" },
	},
})

